mapper.select:
SELECT sys01_ics_comply_cycle_type
  FROM sys01_company
 WHERE sys01_company_id = #{companyId}

SELECT ics31_compliance_write_id                  AS compliance_write_id,
       ics31_compliance_id                        AS compliance_id,
       ics31_answer_cd                            AS answer_code,
       ics31_reason                               AS reason,
       COALESCE(ics31_fix_yn,'false') = 'true'     AS fix_yn,
       COALESCE(ics31_confirm_yn,'false') = 'true' AS confirm_yn
  FROM ics31_compliance_write
 WHERE ics31_compliance_write_id = #{complianceWriteId}
   AND ics31_company_id = #{companyId}
   AND ics31_person_id  = #{personId}

SELECT ics31_compliance_write_id                  AS compliance_write_id,
       ics31_compliance_id                        AS compliance_id,
       ics31_answer_cd                            AS answer_code,
       ics31_reason                               AS reason,
       COALESCE(ics31_fix_yn,'false') = 'true'     AS fix_yn,
       COALESCE(ics31_confirm_yn,'false') = 'true' AS confirm_yn
  FROM ics31_compliance_write
 WHERE ics31_company_id    = #{companyId}
   AND ics31_compliance_id = #{complianceId}
   AND ics31_person_id     = #{personId}
   AND ics31_yyyymm        = #{yyyymm}
   AND ics31_cycle_type    = #{cycleType}
 ORDER BY ics31_compliance_write_id

mapper.update:
UPDATE ics31_compliance_write
   SET ics31_answer_cd = #{answerCode}
 WHERE ics31_compliance_write_id = #{complianceWriteId}
   AND ics31_company_id = #{companyId}
   AND ics31_person_id  = #{personId}

UPDATE ics31_compliance_write
   SET ics31_reason = #{reason}
 WHERE ics31_compliance_write_id = #{complianceWriteId}
   AND ics31_company_id = #{companyId}
   AND ics31_person_id  = #{personId}

UPDATE ics31_compliance_write
   SET ics31_fix_yn = #{fixYn},
       ics31_fix_datetime = CASE WHEN #{fixYn} = 'true' THEN f_sysdate() ELSE NULL END,
       ics31_confirmer_id = CASE WHEN #{fixYn} = 'true' THEN #{confirmerId} ELSE ics31_confirmer_id END
 WHERE ics31_compliance_write_id = #{complianceWriteId}
   AND ics31_company_id = #{companyId}
   AND ics31_person_id  = #{personId}

mapper.select:
SELECT count(*)
  FROM ics32_relate_appr
       LEFT OUTER JOIN apr01_appr b ON ics32_appr_id = apr01_appr_id
 WHERE ics32_company_id = #{companyId}
   AND b.apr01_status_cd IN ('10', '20', '30')
   AND ics32_yyyymm     = #{yyyymm}
   AND ics32_cycle_type = #{cycleType}
   AND ics32_appr_type  = '2'
   AND ics32_person_id  = #{personId}

mapper.delete:
DELETE FROM ics31_compliance_write
 WHERE ics31_compliance_write_id = #{complianceWriteId}
   AND ics31_company_id = #{companyId}
   AND ics31_person_id  = #{personId}
